/**
 * Script de Migración de Biblioteca de Ejercicios
 * 
 * Este script:
 * 1. Crea backup completo de la base de datos
 * 2. Identifica ejercicios asignados a rutinas de usuarios
 * 3. Actualiza la biblioteca con nuevos ejercicios organizados por grupos musculares
 * 4. Convierte descansos de segundos a minutos
 * 5. Preserva ejercicios ya asignados a rutinas
 */

require('dotenv').config();
const { MongoClient } = require('mongodb');
const { newExercisesLibrary } = require('./new-exercises-data');
const fs = require('fs');
const path = require('path');

const MONGO_URL = process.env.MONGODB_URI;

async function runMigration() {
    if (!MONGO_URL) {
        console.error('❌ Error: La variable de entorno MONGODB_URI no está definida.');
        process.exit(1);
    }

    let client;
    try {
        // Conectar a MongoDB
        console.log('🔄 Conectando a MongoDB Atlas...');
        client = new MongoClient(MONGO_URL);
        await client.connect();
        const db = client.db();
        console.log(`✅ Conectado a la base de datos: ${db.databaseName}\n`);

        // ========== PASO 1: CREAR BACKUP ==========
        console.log('📦 PASO 1: Creando backup de la base de datos...');
        const collections = ['system', 'clients', 'trainers', 'notifications'];
        const backupData = {};

        for (const collName of collections) {
            const data = await db.collection(collName).find({}).toArray();
            backupData[collName] = data;
            console.log(`   ✓ Backup de colección "${collName}": ${data.length} documentos`);
        }

        const backupFilePath = path.join(__dirname, `backup-${Date.now()}.json`);
        fs.writeFileSync(backupFilePath, JSON.stringify(backupData, null, 2));
        console.log(`✅ Backup creado exitosamente en: ${backupFilePath}\n`);

        // ========== PASO 2: IDENTIFICAR EJERCICIOS ASIGNADOS ==========
        console.log('🔍 PASO 2: Identificando ejercicios asignados a rutinas...');
        const clients = await db.collection('clients').find({}).toArray();
        const assignedExerciseIds = new Set();

        clients.forEach(client => {
            if (client.customRoutine && Array.isArray(client.customRoutine)) {
                client.customRoutine.forEach(week => {
                    Object.keys(week).forEach(day => {
                        if (week[day].exercises && Array.isArray(week[day].exercises)) {
                            week[day].exercises.forEach(exercise => {
                                if (exercise.exerciseId) {
                                    assignedExerciseIds.add(exercise.exerciseId);
                                }
                            });
                        }
                    });
                });
            }
        });

        console.log(`   ℹ️  Encontrados ${assignedExerciseIds.size} ejercicios únicos asignados a rutinas`);
        console.log(`   📋 IDs de ejercicios asignados: ${Array.from(assignedExerciseIds).join(', ')}\n`);

        // ========== PASO 3: OBTENER EJERCICIOS ACTUALES ==========
        console.log('📚 PASO 3: Obteniendo biblioteca actual de ejercicios...');
        const systemDoc = await db.collection('system').findOne({ _id: 'exercises' });
        const currentExercises = systemDoc?.data || [];
        console.log(`   ✓ Ejercicios actuales en biblioteca: ${currentExercises.length}\n`);

        // ========== PASO 4: PRESERVAR EJERCICIOS ASIGNADOS ==========
        console.log('💾 PASO 4: Preservando ejercicios asignados...');
        const preservedExercises = currentExercises.filter(ex => {
            const isAssigned = assignedExerciseIds.has(ex.id);
            if (isAssigned) {
                console.log(`   ✓ Preservando: "${ex.name}" (ID: ${ex.id})`);
                // Convertir descanso de segundos a minutos si es necesario
                if (ex.rest && ex.rest > 10) {
                    const oldRest = ex.rest;
                    ex.rest = Math.round(ex.rest / 60 * 10) / 10; // Convertir a minutos con 1 decimal
                    console.log(`      └─ Descanso actualizado: ${oldRest} seg → ${ex.rest} min`);
                }
            }
            return isAssigned;
        });
        console.log(`   ✅ Total de ejercicios preservados: ${preservedExercises.length}\n`);

        // ========== PASO 5: COMBINAR CON NUEVA BIBLIOTECA ==========
        console.log('🔄 PASO 5: Combinando con nueva biblioteca de ejercicios...');
        
        // Filtrar ejercicios nuevos que no estén ya preservados
        const preservedIds = new Set(preservedExercises.map(ex => ex.id));
        const filteredNewExercises = newExercisesLibrary.filter(ex => !preservedIds.has(ex.id));
        
        const finalExercises = [...filteredNewExercises, ...preservedExercises];
        
        console.log(`   ✓ Nuevos ejercicios en biblioteca: ${filteredNewExercises.length}`);
        console.log(`   ✓ Ejercicios preservados: ${preservedExercises.length}`);
        console.log(`   ✅ Total final de ejercicios: ${finalExercises.length}\n`);

        // ========== PASO 6: ACTUALIZAR BASE DE DATOS ==========
        console.log('💿 PASO 6: Actualizando base de datos...');
        await db.collection('system').updateOne(
            { _id: 'exercises' },
            { $set: { data: finalExercises } },
            { upsert: true }
        );
        console.log('   ✅ Biblioteca de ejercicios actualizada exitosamente\n');

        // ========== PASO 7: ACTUALIZAR DESCANSOS EN RUTINAS DE CLIENTES ==========
        console.log('🔄 PASO 7: Actualizando descansos en rutinas de clientes (seg → min)...');
        let clientsUpdated = 0;
        
        for (const client of clients) {
            let needsUpdate = false;
            
            if (client.customRoutine && Array.isArray(client.customRoutine)) {
                client.customRoutine.forEach(week => {
                    Object.keys(week).forEach(day => {
                        if (week[day].exercises && Array.isArray(week[day].exercises)) {
                            week[day].exercises.forEach(exercise => {
                                // Si rest es mayor a 10, probablemente está en segundos
                                if (exercise.rest && exercise.rest > 10) {
                                    exercise.rest = Math.round(exercise.rest / 60 * 10) / 10;
                                    needsUpdate = true;
                                }
                            });
                        }
                    });
                });

                if (needsUpdate) {
                    await db.collection('clients').updateOne(
                        { id: client.id },
                        { $set: { customRoutine: client.customRoutine } }
                    );
                    clientsUpdated++;
                    console.log(`   ✓ Actualizado cliente: ${client.name || client.username}`);
                }
            }
        }
        console.log(`   ✅ ${clientsUpdated} clientes actualizados\n`);

        // ========== RESUMEN FINAL ==========
        console.log('═'.repeat(70));
        console.log('✅ MIGRACIÓN COMPLETADA EXITOSAMENTE');
        console.log('═'.repeat(70));
        console.log(`📊 RESUMEN:`);
        console.log(`   • Backup guardado en: ${backupFilePath}`);
        console.log(`   • Ejercicios en nueva biblioteca: ${filteredNewExercises.length}`);
        console.log(`   • Ejercicios preservados de rutinas: ${preservedExercises.length}`);
        console.log(`   • Total de ejercicios en biblioteca: ${finalExercises.length}`);
        console.log(`   • Clientes con rutinas actualizadas: ${clientsUpdated}`);
        console.log(`   • Grupos musculares disponibles:`);
        
        const groups = {};
        finalExercises.forEach(ex => {
            if (!groups[ex.category]) groups[ex.category] = 0;
            groups[ex.category]++;
        });
        
        Object.entries(groups).sort().forEach(([category, count]) => {
            console.log(`     - ${category}: ${count} ejercicios`);
        });
        
        console.log('═'.repeat(70));
        console.log('🎉 ¡Migración completada! Descansos ahora están en MINUTOS.\n');

    } catch (error) {
        console.error('\n❌ ERROR durante la migración:', error);
        console.error('Stack trace:', error.stack);
        process.exit(1);
    } finally {
        if (client) {
            await client.close();
            console.log('🔌 Conexión a MongoDB cerrada.');
        }
    }
}

// Ejecutar la migración
if (require.main === module) {
    runMigration()
        .then(() => {
            console.log('\n✅ Script de migración finalizado exitosamente.');
            process.exit(0);
        })
        .catch((error) => {
            console.error('\n❌ Error fatal:', error);
            process.exit(1);
        });
}

module.exports = { runMigration };
